const html = $input.first()?.json?.data || '';
if (!html) return [];

const tenders = [];
const itemRegex = /<li[^>]*class="[^"]*offre-item[^"]*"[\s\S]*?<\/li>/gi;
const matches = html.match(itemRegex) || [];

for (const block of matches) {
  const titleMatch = block.match(/<a[^>]*class="[^"]*offre-title[^"]*"[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/i);
  const buyerMatch = block.match(/<span[^>]*class="[^"]*offre-org[^"]*"[^>]*>([\s\S]*?)<\/span>/i);
  const dateMatch = block.match(/<span[^>]*class="[^"]*offre-date[^"]*"[^>]*>([\s\S]*?)<\/span>/i);
  const idMatch = block.match(/data-id="(\d+)"/i) || block.match(/offre-(\d+)/i);

  if (titleMatch) {
    const rawTitle = titleMatch[2].replace(/<[^>]*>/g, '').trim();
    const url = titleMatch[1].startsWith('http') ? titleMatch[1] : 'https://www.appeloffres.com' + titleMatch[1];
    const buyer = buyerMatch ? buyerMatch[1].replace(/<[^>]*>/g, '').trim() : 'Organisme Public Tunisien';
    const dateStr = dateMatch ? dateMatch[1].replace(/<[^>]*>/g, '').trim() : '';
    const id = idMatch ? 'AO-' + idMatch[1] : 'AO-' + Math.random().toString(36).substr(2, 9);

    tenders.push({
      json: {
        id,
        source: 'appeloffres.com',
        domain: 'IT / Telecoms',
        description: rawTitle,
        buyer,
        country: 'Tunisia',
        published_date: dateStr || new Date().toISOString().split('T')[0],
        deadline: '',
        url,
        detected_at: new Date().toISOString(),
        status: 'active'
      }
    });
  }
}

return tenders.slice(0, 10);

const notices = $input.first()?.json?.notices || [];
if (!Array.isArray(notices) || notices.length === 0) return [];

return notices.map(notice => {
  const title = notice['notice-title']?.eng 
    || Object.values(notice['notice-title'] || {})[0] 
    || 'No title';

  const buyerName = notice['buyer-name']
    ? Object.values(notice['buyer-name'])[0]?.[0] || 'Unknown Buyer'
    : 'Unknown Buyer';

  const country = notice['buyer-country']?.[0] || 'EU';
  const pubNumber = notice['publication-number'] || '';
  const pubDate = notice['publication-date']?.split('+')[0] || '';
  const cpvCodes = (notice['classification-cpv'] || []).join(', ');
  const url = 'https://ted.europa.eu/en/notice/-/detail/' + pubNumber;

  return {
    json: {
      id: 'TED-' + pubNumber,
      source: 'ted.europa.eu',
      domain: 'IT / Software Services',
      description: title,
      reference: pubNumber,
      country: country,
      published_date: pubDate || new Date().toISOString().split('T')[0],
      deadline: '',
      url: url,
      detected_at: new Date().toISOString(),
      status: 'active',
      cpv_codes: cpvCodes,
      buyer: buyerName
    }
  };
});

const items = $input.first()?.json?.data || [];
if (!Array.isArray(items) || items.length === 0) {
  return [{ json: { prompt: '', count: 0, items: [] } }];
}

const listStr = items.map((t, i) => `[${i + 1}] ${t.buyer} | ${t.country} | ${t.description.slice(0, 160)}`).join('\n');

const prompt = `Identify all genuine IT, software engineering, digital transformation, cloud, cybersecurity, or data platform tenders. Return a JSON object with a single key 'relevant' containing an array of 1-based integer indices of relevant tenders. Example: {"relevant": [1, 3]}\n\nTenders:\n${listStr}`;

return [{
  json: {
    prompt,
    count: items.length,
    items
  }
}];

