const raw = $input.first()?.json?.choices?.[0]?.message?.content || '{}';
let indices = [];
try {
  const parsed = JSON.parse(raw);
  indices = Array.isArray(parsed.relevant) ? parsed.relevant : [];
} catch(e) {
  const matches = raw.match(/\d+/g) || [];
  indices = matches.map(Number);
}

const tenders = $('Aggregate All Tenders').first()?.json?.data || [];

if ((!indices || indices.length === 0) && tenders.length > 0) {
  indices = tenders.map((_, idx) => idx + 1);
}

const relevant = indices
  .filter(i => Number.isInteger(i) && i >= 1 && i <= tenders.length)
  .map(i => {
    const t = tenders[i - 1];
    return {
      json: {
        ...t,
        llm_classified: true
      }
    };
  });

relevant.sort((a, b) => {
  const dateA = a.json.published_date || '';
  const dateB = b.json.published_date || '';
  return dateB.localeCompare(dateA);
});

// Take top 3 for live search and proposal processing in this run
return relevant.slice(0, 3);

const tender = $input.first().json;
const buyer = tender.buyer || 'Organisme Public';
const country = tender.country || 'Tunisia';

const buyerQuery = `"${buyer}" ${country} IT projects technology budget`;
const sectorQuery = `"${buyer}" digital transformation software`;

return [{
  json: {
    ...tender,
    tender_id: tender.id,
    search_query_1: buyerQuery,
    search_query_2: sectorQuery
  }
}];

const tender = $('Build Prospect Search Queries').item.json;
const res1 = $('Serper: Search Buyer Projects').item?.json || {};
const res2 = $input.first()?.json || {};

const extractSnippets = (data) => {
  const organic = data.organic || [];
  return organic.map(item => ({
    title: item.title || '',
    snippet: item.snippet || '',
    link: item.link || ''
  }));
};

const results1 = extractSnippets(res1);
const results2 = extractSnippets(res2);
const allResults = [...results1, ...results2];

const searchContext = allResults.length > 0
  ? allResults.map((r, i) => `[${i + 1}] ${r.title}\n${r.snippet}\nSource: ${r.link}`).join('\n\n')
  : 'No live web search results found for this organization.';

return [{
  json: {
    ...tender,
    search_context: searchContext
  }
}];

