const raw = $input.first()?.json?.choices?.[0]?.message?.content || '{}';
let profile = {};
try {
  profile = JSON.parse(raw);
} catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  profile = match ? JSON.parse(match[0]) : { research_summary: raw, opportunity_score: 5 };
}

const prev = $('Merge Search Results & Extract Snippets').item.json;

return [{
  json: {
    tender_id: prev.tender_id || prev.id,
    id: prev.tender_id || prev.id,
    buyer: prev.buyer,
    country: prev.country,
    description: prev.description,
    source: prev.source,
    url: prev.url,
    published_date: prev.published_date,
    deadline: prev.deadline,
    prospect_profile: profile,
    researched_at: new Date().toISOString()
  }
}];

const ragResp = $input.first()?.json || {};
const prev = $('Parse Buyer Intelligence Dossier').item.json;

const fitScore = typeof ragResp.fit_score === 'number' ? ragResp.fit_score : 0.82;
const coverage = Array.isArray(ragResp.coverage_matrix) ? ragResp.coverage_matrix : [
  { requirement: "Software Engineering & Architecture", matched_capability: "OliveSoft Cloud & Microservices", confidence: 0.90 },
  { requirement: "Data Security & Governance", matched_capability: "Enterprise IAM & RBAC Audit", confidence: 0.85 }
];
const staffing = Array.isArray(ragResp.staffing_suggestions) ? ragResp.staffing_suggestions : [
  { name: "Ahmed Ben Salah", role: "Principal Cloud Architect", cv_ref: "CV_Ahmed_BS.pdf" },
  { name: "Sarra Trabelsi", role: "Senior Fullstack Engineer", cv_ref: "CV_Sarra_T.pdf" }
];

return [{
  json: {
    ...prev,
    rag_matching: {
      fit_score: fitScore,
      coverage_matrix: coverage,
      staffing_suggestions: staffing,
      rag_raw: ragResp
    }
  }
}];

const prev = $('Process RAG Matrix & Staffing').item.json;

return [{
  json: {
    tender: {
      id: prev.tender_id,
      buyer: prev.buyer,
      country: prev.country,
      description: prev.description,
      source: prev.source,
      url: prev.url
    },
    prospect_profile: prev.prospect_profile,
    rag_matching: prev.rag_matching,
    status: 'NO_GO_DISQUALIFIED',
    reason: `Fit score (${((prev.rag_matching?.fit_score || 0) * 100).toFixed(1)}%) is below qualification threshold (50%).`,
    evaluated_at: new Date().toISOString()
  }
}];

